# =============================================================================
# Public Helper Functions
# =============================================================================

# List available database connections
gash_db_list() {
    declare -F __gash_load_env >/dev/null 2>&1 && __gash_load_env
    __gash_call gash_db_list "$@"
}

# Test a database connection
gash_db_test() {
    declare -F __gash_load_env >/dev/null 2>&1 && __gash_load_env
    __gash_call gash_db_test "$@"
}

