    [[ -z "$__GASH_ENV_AI_PROVIDERS" ]] && return 1

    local first_line="${__GASH_ENV_AI_PROVIDERS%%$'\n'*}"
    [[ -z "$first_line" ]] && return 1

    printf '%s' "${first_line%%$'\t'*}"
    return 0
